class bestbook_award(delegate.page):
    path = r"/works/OL(\d+)W/awards"
    encoding = "json"

    @jsonapi
    def POST(self, work_id):
        user = accounts.get_current_user()
        if not user:
            return json.dumps({'errors': 'Authentication failed'})

        i = web.input(op=None, topic=None, comment='', edition_key=None)
        if web.ctx.env.get('CONTENT_TYPE', '').split(';', 1)[0] == 'application/json':
            try:
                i.update(json.loads(web.data()))
            except (ValueError, TypeError):
                return json.dumps({'errors': 'Invalid JSON'})

        username = user.key.split('/')[2]
        try:
            if i.op not in ('add', 'remove', 'update'):
                raise Bestbook.AwardConditionsError('Invalid operation')
            if i.op == 'remove':
                rows = Bestbook.remove(username, work_id=work_id)
                return json.dumps({'success': True, 'rows': rows})
            edition_id = (
                int(extract_numeric_id_from_olid(i.edition_key))
                if i.edition_key else None
            )
            operation = Bestbook.add if i.op == 'add' else Bestbook.update
            award = operation(username, work_id, i.topic, i.comment, edition_id)
            return json.dumps({'success': True, 'award': award})
        except (Bestbook.AwardConditionsError, ValueError, TypeError) as exc:
            return json.dumps({'errors': str(exc)})


